@Gnbrkm41 I am not able to repro it so far. I have tried on 2 machines with different architecture. could you please create a stand alone dotnet app and run the following code:

```C#
using System;
using System.Runtime.InteropServices;
using System.Reflection;
using System.Globalization;

namespace apps
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine(RuntimeInformation.OSDescription);
            Console.WriteLine(RuntimeInformation.FrameworkDescription);
            Console.WriteLine($"UseNls: {typeof(object).Assembly.GetType("System.Globalization.GlobalizationMode").GetProperty("UseNls", BindingFlags.NonPublic | BindingFlags.Static).GetValue(null)}");
            Console.WriteLine($"Invariant: {typeof(object).Assembly.GetType("System.Globalization.GlobalizationMode").GetProperty("Invariant", BindingFlags.NonPublic | BindingFlags.Static).GetValue(null)}");

            CultureInfo ci = new CultureInfo("ko-KR");
            foreach (char c in ci.TextInfo.ToLower("\U00010400"))
            {
                Console.Write($"\\u{(int)c:x4}, ");
            }
            Console.WriteLine();
        }
    }
}
```

